fn trace(a: Vec<Vec<f32>>, offset: i32) -> f32 {
    a.iter()
     .enumerate()
     .filter_map(|(i, row)| {
         // compute the target column index as an i32
         let j = i as i32 + offset;
         // skip negative indices
         if j < 0 {
             None
         } else {
             // try to get the element at position j (as usize)
             row.get(j as usize).copied()
         }
     })
     .sum()
}

